insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('petra','البتراء','tourism','published','maan','معان','موقع أثري منحوت في الصخر بين البحر الأحمر والبحر الميت، وكان عاصمة الأنباط. وصفته اليونسكو بأنه نصفه مبني ونصفه منحوت في الصخر، ويحيط به جبال تقطعها ممرات وأخوار. كان في العصرين الهلنستي والروماني مركزًا رئيسيًا للقوافل وملتقى طرق بين الجزيرة العربية ومصر وبلاد الشام، ومكّن نظام إدارة المياه فيه من الاستيطان في منطقة جافة. أُدرج في قائمة التراث العالمي عام 1985.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'UNESCO World Heritage Centre','https://whc.unesco.org/en/list/326',now(),true)
