insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('wadi-rum','محمية وادي رم','tourism','published','aqaba','العقبة','محمية في جنوب الأردن قرب الحدود مع السعودية، مساحتها نحو 74 ألف هكتار، وأُدرجت في التراث العالمي عام 2011 كموقع طبيعي وثقافي مختلط. تضم أخوارًا ضيقة وأقواسًا طبيعية وجروفًا شاهقة، وتدل النقوش الصخرية والآثار على نحو 12 ألف سنة من الاستيطان البشري، وفيها نحو 25 ألف نقش صخري و20 ألف كتابة.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'UNESCO World Heritage Centre','https://whc.unesco.org/en/list/1377',now(),true)
