insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('baptism-site-al-maghtas','موقع المغطس (بيت عنيا عبر الأردن)','tourism','published',NULL,NULL,'موقع أثري على الضفة الشرقية لنهر الأردن، على بعد نحو تسعة كيلومترات شمال البحر الميت، يُعتقد أنه المكان الذي عُمّد فيه المسيح على يد يوحنا المعمدان. يضم بقايا رومانية وبيزنطية منها كنائس وصوامع ودير ومغارات نسّاك وأحواض تعميد، وهو موقع حج مسيحي. أُدرج في التراث العالمي عام 2015.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'UNESCO World Heritage Centre','https://whc.unesco.org/en/list/1446',now(),false)
