insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('quseir-amra','قصير عمرة','tourism','published','zarqa','الزرقاء','قصر صحراوي في البادية الشرقية بمحافظة الزرقاء، بُني في أوائل القرن الثامن الميلادي وكان حصنًا بحامية وإقامة لخلفاء بني أمية. تزيّن قاعة الاستقبال والحمّام فيه رسوم جدارية تصويرية تعكس فن العصر الدنيوي. أُدرج في التراث العالمي عام 1985.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'UNESCO World Heritage Centre','https://whc.unesco.org/en/list/327',now(),false)
