insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('um-er-rasas','أم الرصاص','tourism','published',NULL,NULL,'موقع أثري جنوب شرق مادبا على حافة السهوب شبه الجافة، بدأ معسكرًا رومانيًا وتحوّل إلى بلدة منذ القرن الخامس. فيه معسكر روماني محصّن و16 كنيسة بعضها بأرضيات فسيفساء محفوظة جيدًا، منها كنيسة القديس إسطفانوس، وبرجان مربعان يُرجّح أنهما البقية الوحيدة لنمط الزهد على الأعمدة في المنطقة. معظم الموقع لم يُنقَّب. أُدرج في التراث العالمي عام 2004.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'UNESCO World Heritage Centre','https://whc.unesco.org/en/list/1093',now(),false)
