insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('jerash','جرش (جراسا)','tourism','published','jerash','جرش','مدينة في شمال الأردن ومركز محافظة جرش، تبعد نحو 48 كم شمال عمّان، واسمها القديم جراسا، وتُلقّب «بومبي الشرق الأوسط». من معالمها الساحة البيضاوية ذات الأعمدة الأيونية، ومعابد أرتميس وزيوس، والمسرحان الشمالي والجنوبي، والشارع المعمّد، وقوس هادريان، والميدان (الهيبودروم)، وحمّامات عامة كبيرة، ونافورة (نيمفايوم)، وأسوار شبه كاملة.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Jerash',now(),false)
