insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('amman-citadel','جبل القلعة (قلعة عمّان)','tourism','published','amman','عمّان','موقع أثري على تلة تشرف على وسط البلد في عمّان، واسمه بالعربية «القلعة». يُعد من أقدم الأماكن المأهولة باستمرار في العالم، وكان عاصمة مملكة عمّون. من معالمه المعبد الروماني الكبير (المعروف بمعبد هرقل)، وكنيسة بيزنطية من القرن السادس، والقصر الأموي الذي بناه الخليفة هشام بن عبد الملك، ومتحف الأردن الأثري الذي أُسس عام 1951.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Amman_Citadel',now(),false)
