insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('madaba','مادبا','tourism','published','madaba','مادبا','مركز محافظة مادبا في وسط الأردن، تبعد نحو 30 كم جنوب غرب عمّان. تحفظ أرضية كنيسة القديس جاورجيوس للروم الأرثوذكس (كنيسة الخريطة) خريطة فسيفساء من القرن السادس لأرض الشام، وفيها أقدم تصوير بيزنطي باقٍ للقدس. تشتهر المدينة بفسيفساء من العصرين البيزنطي والأموي.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Madaba',now(),false)
