insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('ajloun-castle','قلعة عجلون','tourism','published','ajloun','عجلون','قلعة إسلامية من القرن الثاني عشر على قمة تلة في جبل عوف شمال غرب الأردن. بناها الأيوبيون، وأُعيد بناؤها قلعةً عام 1184 على يد عز الدين أسامة أحد قادة صلاح الدين، ووسّعها المملوكي أيبك بن عبد الله في 1214–1215.',32.3252,35.7273,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Ajloun_Castle',now(),false)
