insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('mount-nebo','جبل نيبو','tourism','published','madaba','مادبا','جبل في محافظة مادبا يرتفع نحو 700 متر عن سطح البحر ويتبع سلسلة جبال عباريم. يرتبط في الكتاب المقدس بصعود النبي موسى إليه ورؤيته أرض كنعان ووفاته فيه. على قمته كنيسة تذكارية بيزنطية بُنيت في النصف الثاني من القرن الرابع، وأُعيد افتتاح مظلة حماية جديدة فوقها في 15 أكتوبر 2016. زارها البابا يوحنا بولس الثاني عام 2000 والبابا بنديكتوس السادس عشر عام 2009.',31.7667,35.725,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Mount_Nebo',now(),false)
