insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('karak-castle','قلعة الكرك','tourism','published','karak','الكرك','قلعة من العصور الوسطى في مدينة الكرك، من أكبر القلاع في بلاد الشام. بدأ بناؤها في أربعينيات القرن الثاني عشر (1142) في عهد بغدوين الساقي وفولك ملك القدس.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Kerak_Castle',now(),false)
