insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('umm-qais','أم قيس (جدارا)','tourism','published','irbid','إربد','بلدة في أقصى شمال غرب الأردن بمحافظة إربد، قريبة من أطلال مدينة جدارا القديمة، وكانت مركزًا ثقافيًا يونانيًا في العصرين الهلنستي والروماني وعضوًا في الديكابولس. يطل الموقع على بحيرة طبريا ومرتفعات الجولان وأخدود اليرموك، وفيه بيت روسان الذي صار مركز زوار ومتحفًا يعرض تماثيل يونانية وفسيفساء مسيحية.',NULL,NULL,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Umm_Qais',now(),false)
