insert into public.places (id,name,category,status,region_id,region_name,description,lat,lng,alerts,source_name,source_url,verified_at,featured)
values ('dana-biosphere-reserve','محمية ضانا للمحيط الحيوي','tourism','published','tafilah','الطفيلة','محمية في جنوب وسط الأردن أقرب مدنها الطفيلة، مساحتها 308 كم²، أُنشئت عام 1989 وتديرها الجمعية الملكية لحماية الطبيعة. تنحدر من نحو 1500 متر عند هضبة القادسية إلى صحراء وادي عربة، وتضم 703 أنواع نباتية و215 نوعًا من الطيور و38 نوعًا من الثدييات، منها الوعل النوبي والوشق الصحراوي، إضافة إلى تراث أثري وثقافي وسكانها الأصليين العطاعطة.',30.6875,35.5725,array['تحقق من ساعات الدخول والأسعار الحالية من الجهة المشغّلة قبل الزيارة'],'Wikipedia','https://en.wikipedia.org/wiki/Dana_Biosphere_Reserve',now(),false)
