insert into public.places (id,name,category,status,region_id,region_name,description,phone,address,website,opening_hours,alerts,source_name,source_url,verified_at)
values ('civil-status-passports-department','دائرة الأحوال المدنية والجوازات','government','published','amman','عمّان',
'الجهة الحكومية المسؤولة عن إصدار جوازات السفر وهوية الأحوال المدنية الذكية وتسجيل المواليد والزواج والوفيات ودفتر العائلة. تتوفر عبر موقعها خدمات إلكترونية مثل إصدار الجواز لأول مرة وتجديده وتسجيل حساب إلكتروني.',
'+962 6 563 6666','طبربور، عمّان، بجانب ورش الأمن العام','https://www.cspd.gov.jo',
'مكتب الخدمة العاجلة (المبنى الرئيسي في طبربور): صيفًا (1 أبريل–30 سبتمبر) 11:00 ص–7:00 م، شتاءً (1 أكتوبر–31 مارس) 10:00 ص–6:00 م، والجمعة والسبت والعطل الرسمية 10:00 ص–2:00 م',
array['الأوقات المذكورة لمكتب الخدمة العاجلة في المبنى الرئيسي فقط؛ تحقق من الموقع الرسمي للتغييرات'],
'الموقع الرسمي لدائرة الأحوال المدنية والجوازات','https://www.cspd.gov.jo',now())
